package io.github.thomasfissh.androidgamepadbridge;
import android.app.*;import android.os.*;import android.content.*;import android.hardware.usb.*;import android.view.*;import android.widget.*;
public class MainActivity extends Activity {
 TextView text;CheckBox compat;Handler h=new Handler();long keys=0,moves=0;java.util.TreeSet<Integer> seenKeys=new java.util.TreeSet<>();int[] axes={0,1,11,14,23,22,15,16};float[] mins=new float[8],maxs=new float[8];String last="未收到虚拟手柄输入";
 final Runnable update=new Runnable(){public void run(){if(text!=null)text.setText("USB 手柄 · 2.4G 独立桥接\n\n"+BridgeService.status+"\n\n系统输入回读：按键="+keys+" 摇杆="+moves+"\n"+last+"\n键码="+seenKeys+"\n轴最小="+java.util.Arrays.toString(mins)+"\n轴最大="+java.util.Arrays.toString(maxs)+"\n\n测试时按 A/B/X/Y、方向键、扳机并转动摇杆。Select＋Start 呼出菜单。停止时释放接收器输入。");h.postDelayed(this,500);}};
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(32,16,32,16);text=new TextView(this);text.setTextSize(17);l.addView(text,new LinearLayout.LayoutParams(-1,0,1));compat=new CheckBox(this);compat.setText("内置手柄兼容（Retroid 系统授权，死亡细胞）");boolean available=NativePad.canUse()||OemInputGrant.available();if(!available){getSharedPreferences("bridge",0).edit().putBoolean("builtin_mode",false).apply();compat.setText("内置手柄兼容：缺少系统授权（暂不可用）");}compat.setEnabled(available);compat.setChecked(available&&getSharedPreferences("bridge",0).getBoolean("builtin_mode",false));compat.setOnCheckedChangeListener((button,checked)->getSharedPreferences("bridge",0).edit().putBoolean("builtin_mode",checked).apply());l.addView(compat);Button start=new Button(this);start.setText("启动桥接");start.setOnClickListener(v->request());l.addView(start);Button diag=new Button(this);diag.setText("背键采样（20秒）");diag.setOnClickListener(v->{BridgeService.diagnosticUntil=SystemClock.elapsedRealtime()+20000;android.util.Log.i("GamepadRaw","BEGIN");});l.addView(diag);Button rumble=new Button(this);rumble.setText("震动测试（0.3秒）");rumble.setOnClickListener(v->{if(BridgeService.compatActive&&BridgeService.isRunning()){BridgeService.testRumbleUntil=SystemClock.elapsedRealtime()+300;return;}for(int id:InputDevice.getDeviceIds()){InputDevice d=InputDevice.getDevice(id);if(d!=null&&d.getName().equals("Gamepad Bridge Controller")){d.getVibrator().vibrate(VibrationEffect.createOneShot(300,VibrationEffect.DEFAULT_AMPLITUDE));}}});l.addView(rumble);Button stop=new Button(this);stop.setText("停止桥接");stop.setOnClickListener(v->stopService(new Intent(this,BridgeService.class)));l.addView(stop);setContentView(l);h.post(update);handleStartIntent(getIntent());}
 void handleStartIntent(Intent intent){if(intent!=null&&intent.getBooleanExtra("gamepad_start",false)){intent.removeExtra("gamepad_start");android.util.Log.i("GamepadLaunch","Start saved mode requested");h.postDelayed(()->request(),400);}}
 protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);handleStartIntent(intent);}
 void request(){if(BridgeService.isRunning() && compat.isChecked()!=BridgeService.compatActive){stopService(new Intent(this,BridgeService.class));h.postDelayed(()->request(),700);return;}UsbManager m=(UsbManager)getSystemService(USB_SERVICE);for(UsbDevice d:m.getDeviceList().values())if(d.getVendorId()==0x2345&&d.getProductId()==0xe053){if(m.hasPermission(d)){startForegroundService(new Intent(this,BridgeService.class));return;}String action=getPackageName()+".USB_PERMISSION";BroadcastReceiver r=new BroadcastReceiver(){public void onReceive(Context c,Intent i){unregisterReceiver(this);if(m.hasPermission(d))startForegroundService(new Intent(MainActivity.this,BridgeService.class));else BridgeService.status="USB 授权未通过";}};registerReceiver(r,new IntentFilter(action));m.requestPermission(d,PendingIntent.getBroadcast(this,0,new Intent(action).setPackage(getPackageName()),PendingIntent.FLAG_MUTABLE|PendingIntent.FLAG_UPDATE_CURRENT));return;}BridgeService.status="未找到 2345:e053 接收器";}
 boolean own(InputEvent e){InputDevice d=e.getDevice();return d!=null&&d.getName().equals(BridgeService.compatActive?"Retroid Pocket Controller":"Gamepad Bridge Controller");}
 public boolean dispatchKeyEvent(KeyEvent e){if(own(e)){keys++;seenKeys.add(e.getKeyCode());android.util.Log.i("GamepadInput","key="+e.getKeyCode()+" action="+e.getAction());last="key="+e.getKeyCode()+" action="+e.getAction();return true;}return super.dispatchKeyEvent(e);}
 public boolean dispatchGenericMotionEvent(MotionEvent e){if(own(e)){moves++;for(int j=0;j<axes.length;j++){float v=e.getAxisValue(axes[j]);mins[j]=Math.min(mins[j],v);maxs[j]=Math.max(maxs[j],v);}last=String.format(java.util.Locale.US,"左 X %.2f Y %.2f 右 Z %.2f RZ %.2f LT %.2f RT %.2f",e.getAxisValue(0),e.getAxisValue(1),e.getAxisValue(11),e.getAxisValue(14),e.getAxisValue(23),e.getAxisValue(22));return true;}return super.dispatchGenericMotionEvent(e);}
 public void onDestroy(){h.removeCallbacks(update);super.onDestroy();}
}
